INSERT INTO static_pages (title, link, context, is_homepage, content) VALUES
('Find Out More', 'budg.local:9999/about', '-', FALSE, '<div class="hero-unit"><h1>Welcome to <br/>abdo alaa application.</h1><p class="description">BUDG Data Governance is our collaborative and shared view of the business. Discover how we depend on each other to deliver, where changes are planned, and how projects are impacted. Trace the lifecycle of information and connect with a broad community of stakeholders with clearly defined responsibilities.</p><p><a href="/search" class="hero-explore"><i class="icon-search4"></i> Explore with Unison &rarr;</a></p>{% if app.user == '' %}<p><a href="/login" class="hero-login openLoginPopup"><i class="icon-reading"></i> Login and start contributing &rarr;</a></p>{% endif %}<p><a href="/about" class="hero-more"><i class="icon-question7"></i> Find out more &rarr;</a></p></div>'),
('Homepage', 'budg.local:9999/home', '-', TRUE, '<div class="hero-unit"><h1>Welcome to <br/>abdo alaa application.</h1><p class="description">BUDG Data Governance is our collaborative and shared view of the business. Discover how we depend on each other to deliver, where changes are planned, and how projects are impacted. Trace the lifecycle of information and connect with a broad community of stakeholders with clearly defined responsibilities.</p><p><a href="/search" class="hero-explore"><i class="icon-search4"></i> Explore with Unison &rarr;</a></p>{% if app.user == '' %}<p><a href="/login" class="hero-login openLoginPopup"><i class="icon-reading"></i> Login and start contributing &rarr;</a></p>{% endif %}<p><a href="/about" class="hero-more"><i class="icon-question7"></i> Find out more &rarr;</a></p></div>'),
